Func<Orc.Game.Commanding.ActionQuotaView, Context, CancellationToken, Task> HandleAsync = async (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return; }
    if (view.Unit is not Orc.Game.Cards.UnitCard unit || !object.ReferenceEquals(unit, host)) { return; }

    // 机动：本次行动的额度消耗减一（对本单位攻击额度 +1），随后失去「机动」。
    var command = host.GetData<Orc.Game.Cards.CommandData>();
    command.SetAttackQuota(command.AttackQuota + 1);
    await host.Keywords.RevokeAsync("机动");
};
